import { createServer } from "node:http";

// Per-deploy config comes from the environment at startup
const paymentsUrl = process.env.PAYMENTS_URL;
if (!paymentsUrl) {
  throw new Error("PAYMENTS_URL is not set");
}

createServer((_req, res) => {
  res.end("ok");
}).listen(8080, () => {
  console.log(`shop-api 1.4.0, payments at ${paymentsUrl}`);
});
